import{_ as t,o as a,c as d,a3 as s}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"数据权限","description":"","frontmatter":{},"headers":[],"relativePath":"backend/data-permission.md","filePath":"backend/data-permission.md","lastUpdated":1786258579000}'),o={name:"backend/data-permission.md"};function n(c,e,r,i,l,p){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="数据权限" tabindex="-1">数据权限 <a class="header-anchor" href="#数据权限" aria-label="Permalink to &quot;数据权限&quot;">​</a></h1><p>权限码回答「<strong>能不能做</strong>这个操作」，数据权限回答「<strong>能对哪些行做</strong>」「<strong>能看到哪些字段</strong>」。两者是独立的维度——有权限码但查不到数据、能查到但某些列被打码，都是数据权限在起作用。</p><p>权限码本身见 <a href="./permission">权限管理</a>。</p><h2 id="两个维度" tabindex="-1">两个维度 <a class="header-anchor" href="#两个维度" aria-label="Permalink to &quot;两个维度&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一次请求要过的门：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  权限码        能不能调这个接口          → 不过：403</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>  数据范围      能操作哪些行              → 不过：查不到 / 改不动（不是 403）</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>  字段级安全    能看哪些列、能改哪些列    → 不过：值被置空或被打码</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">「有权限但列表是空的」不是 bug</p><p>返回 <code>200</code> 且 <code>items</code> 为空、而不是 <code>403</code>——这是数据范围在起作用。排查方向是数据范围配置，不是权限码。</p></div><h2 id="数据范围-行级" tabindex="-1">数据范围（行级） <a class="header-anchor" href="#数据范围-行级" aria-label="Permalink to &quot;数据范围（行级）&quot;">​</a></h2><p>范围枚举是 <code>DataPermissionScope</code>：角色的档位写在 <code>SysRole.DataScope</code>；<code>SysUser.DataScopeOverride</code> 是用户级档位，取 <code>Custom</code> 时才能维护用户级部门明细。</p><table tabindex="0"><thead><tr><th>范围</th><th>含义</th><th>依赖</th></tr></thead><tbody><tr><td><code>SelfOnly</code></td><td>仅本人数据</td><td>—</td></tr><tr><td><code>DepartmentOnly</code></td><td>本部门</td><td><code>SysUserDepartment</code> 的<strong>全部有效部门归属</strong></td></tr><tr><td><code>DepartmentAndChildren</code></td><td>本部门及下级</td><td>部门<strong>闭包表</strong></td></tr><tr><td><code>All</code></td><td>全部数据（仍受租户过滤器约束）</td><td>—</td></tr><tr><td><code>Custom</code></td><td>指定部门集合</td><td><code>Sys_Role_Data_Scope</code> / <code>Sys_User_Data_Scope</code></td></tr></tbody></table><p>解析入口是 <code>IUserDataScopeFilterService.ResolveAccessibleUsersAsync</code>，当前由用户列表查询（<code>UserQueryService</code>）调用；持有 <code>super_admin</code> 角色的用户不受数据范围限制。</p><h3 id="合并规则" tabindex="-1">合并规则 <a class="header-anchor" href="#合并规则" aria-label="Permalink to &quot;合并规则&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>角色的数据范围        →  多角色取并集；任一角色为 All 即放行全部</span></span>
<span class="line"><span>        +</span></span>
<span class="line"><span>用户级自定义部门      →  Sys_User_Data_Scope 的部门按 Custom 并入同一并集</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>一个部门都没命中      →  退回仅本人</span></span></code></pre></div><p>用户级自定义部门要求 <code>SysUser.DataScopeOverride = Custom</code> 才能维护，用于「这个人比较特殊」的场景，不要拿它当常规手段——角色才是可维护的授权单位。</p><h3 id="依赖组织架构" tabindex="-1">依赖组织架构 <a class="header-anchor" href="#依赖组织架构" aria-label="Permalink to &quot;依赖组织架构&quot;">​</a></h3><p><code>DepartmentOnly</code> 与 <code>DepartmentAndChildren</code> 完全依赖 <a href="./organization">组织架构</a>：</p><ul><li><code>DepartmentOnly</code> 取用户在当前租户下<strong>全部状态有效的部门归属</strong>（<code>SysUserDepartment</code>，不区分 <code>IsMain</code>）；</li><li><code>DepartmentAndChildren</code> 在此基础上靠<strong>部门闭包表</strong>一次展开整棵子树。</li></ul><div class="danger custom-block"><p class="custom-block-title">闭包表失真 = 数据范围算错</p><p>闭包表是查询加速镜像，<strong>所有写入必须由 <code>SysDepartment</code> 变更触发</strong>。绕过服务层直改部门表会让闭包表失真，表现是某些下级部门的数据看不到、或看到了本不该看到的。</p><p>修复要重建该子树的闭包，不要手工补行。</p></div><h3 id="组织变更的连锁影响" tabindex="-1">组织变更的连锁影响 <a class="header-anchor" href="#组织变更的连锁影响" aria-label="Permalink to &quot;组织变更的连锁影响&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变更</th><th>影响</th></tr></thead><tbody><tr><td>移动部门</td><td>闭包表重建 → 该子树下所有人的 <code>DepartmentAndChildren</code> 范围变化</td></tr><tr><td>改用户部门归属</td><td>该用户的 <code>DepartmentOnly</code> / <code>DepartmentAndChildren</code> 范围变化</td></tr><tr><td>改角色数据范围</td><td>该角色下所有用户的可见范围变化</td></tr></tbody></table><p>数据范围每次请求实时从库解析，不进授权快照；角色写入路径会失效授权快照（<code>InvalidateAuthorizationAsync</code>），部门写入路径失效组织缓存（<code>InvalidateOrganizationAsync</code>）。</p><h2 id="字段级安全-列级" tabindex="-1">字段级安全（列级） <a class="header-anchor" href="#字段级安全-列级" aria-label="Permalink to &quot;字段级安全（列级）&quot;">​</a></h2><p><code>SysFieldLevelSecurity</code> 按「资源 × 字段 × 主体」定义规则：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>fieldName</code></td><td>字段名（对应实体 / DTO 的属性名）</td></tr><tr><td><code>isReadable</code></td><td>能否读取。不可读 → <strong>值被服务端置空或按脱敏策略改写</strong>，属性本身仍在响应里</td></tr><tr><td><code>isEditable</code></td><td>能否编辑。不可编辑 → 后端写校验直接拒绝（<code>EnsureEditableAsync</code> / <code>EnsureUpdatableAsync</code> 抛异常），前端表单置只读</td></tr><tr><td><code>maskStrategy</code> / <code>maskPattern</code></td><td>脱敏策略与掩码格式（部分脱敏用 <code>keep:N,M</code>，固定替换 / 自定义时 <code>maskPattern</code> 即占位符文本）</td></tr></tbody></table><p>同一字段命中多条规则时按 deny-overrides 合并：任一条不可读即不可读、任一条不可编辑即不可编辑，脱敏取最严的一条。</p><h3 id="脱敏在服务端完成" tabindex="-1">脱敏在服务端完成 <a class="header-anchor" href="#脱敏在服务端完成" aria-label="Permalink to &quot;脱敏在服务端完成&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">后端返回的就是打码后的值</p><p>如 <code>138****8000</code>。<strong>前端不做二次打码</strong>——前端拉取规则只用于两件事：表单置只读、展示「不可见 / 已脱敏」标识。</p><p>这条设计的意义：绕过前端直接调接口也拿不到明文。前端打码是纸糊的。</p></div><p>脱敏由 <code>IFieldSecurityService.ApplyAsync</code> 在查询服务返回前就地改写 DTO（当前接入的资源是 <code>SysUser</code>）。</p><h3 id="过滤与排序也受门控" tabindex="-1">过滤与排序也受门控 <a class="header-anchor" href="#过滤与排序也受门控" aria-label="Permalink to &quot;过滤与排序也受门控&quot;">​</a></h3><p>读侧会经 <code>IFieldSecurityService.GuardFiltersAsync</code> / <code>GuardSortsAsync</code> 处理：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前端下发的 filters / sorts</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>剔除「不可读或已脱敏」字段的条件</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>剔完没有有效排序 → 回退该接口的默认排序</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">「排序点了没反应」优先查字段权限</p><p>被 FLS 剔掉时后端<strong>不会报错</strong>，只是安静地不生效。同理「按某字段搜索没效果」也可能是这个原因，而不是前端 bug。</p></div><h3 id="页面怎么接" tabindex="-1">页面怎么接 <a class="header-anchor" href="#页面怎么接" aria-label="Permalink to &quot;页面怎么接&quot;">​</a></h3><p>前端 <code>PageSchema</code> 声明 <code>resourceCode</code>，页面调用 <code>useFieldSecurity(resourceCode)</code> 拉取当前用户的有效规则，再按 <code>isEditable</code> / <code>isReadable</code> 决定表单只读与「不可见 / 已脱敏」标识。</p><div class="warning custom-block"><p class="custom-block-title"><code>resourceCode</code> 缺省则不拉规则</p><p><code>useFieldSecurity</code> 在 <code>resourceCode</code> 为空时直接跳过请求，页面拿不到任何规则。需要 FLS 的页面记得写上。</p></div><h2 id="写路径的租户边界" tabindex="-1">写路径的租户边界 <a class="header-anchor" href="#写路径的租户边界" aria-label="Permalink to &quot;写路径的租户边界&quot;">​</a></h2><p>除了行级与列级，还有一条容易忽略的边界：<strong>读共享 ≠ 写共享</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读：全局过滤器放行 TenantId IN (0, 当前租户)   ← 租户能读到平台全局数据</span></span>
<span class="line"><span>写：禁止改写/删除非本租户行（含 TenantId=0 的全局行）</span></span></code></pre></div><p>实现方式：预读守卫校验取回行的 <code>TenantId</code>，条件写自动追加当前租户 <code>Where</code>。</p><p>维护全局 / 跨租户数据的<strong>唯一合法入口是平台态</strong>（无租户上下文，<code>ICurrentTenant.Change(null)</code>）。</p><h2 id="排查" tabindex="-1">排查 <a class="header-anchor" href="#排查" aria-label="Permalink to &quot;排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>查什么</th></tr></thead><tbody><tr><td>有权限但列表为空</td><td>用户部门归属对不对 → 角色数据范围设成了什么 → 闭包表是否完整</td></tr><tr><td>某些行改不动</td><td>是否跨租户写（读得到不等于写得动）</td></tr><tr><td>列变成 null / 空</td><td>FLS <code>isReadable</code> 为假，服务端已把值置空</td></tr><tr><td>列显示成 <code>***</code></td><td>FLS 脱敏策略生效，服务端已打码</td></tr><tr><td>排序 / 搜索不生效</td><td>该字段被 FLS 剔出条件</td></tr><tr><td>改了数据范围不生效</td><td>该列表是否接了数据范围过滤；用户级自定义部门需 <code>SysUser.DataScopeOverride = Custom</code></td></tr><tr><td>表单该只读却可编辑</td><td>页面 <code>PageSchema.resourceCode</code> 没声明，或页面没调用 <code>useFieldSecurity</code>（后端写校验仍会拒绝）</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./permission">权限管理</a>：权限码、RBAC 继承、ABAC、判定链</li><li><a href="./organization">组织架构</a>：部门树与闭包表</li><li><a href="./multi-tenancy">多租户 SaaS</a>：租户隔离与写路径边界</li><li><a href="./../frontend/permission">前端手册 · 权限与脱敏</a>：前端侧怎么接</li></ul>`,43)])])}const b=t(o,[["render",n]]);export{u as __pageData,b as default};
